de_ep_method de_ep_method_parse(de_ep_str name) {
    for (int i = 1; i < (int)DE_EP_METHOD_COUNT; ++i)
        if (de_ep_str_eq(name, de_ep__methods[i]))
            return (de_ep_method)i;
    return DE_EP_METHOD_UNKNOWN;
}

const char *de_ep_method_name(de_ep_method m) {
    return (int)m > 0 && m < DE_EP_METHOD_COUNT ? de_ep__methods[m] : "";
}

const char *de_ep_method_capability(de_ep_method m) {
    return (int)m > 0 && m < DE_EP_METHOD_COUNT ? de_ep__capabilities[m] : NULL;
}

bool de_ep_read_request(const char *payload, size_t len, de_ep_request *out) {
    memset(out, 0, sizeof(*out));
    mpack_reader_t r;
    mpack_reader_init_data(&r, payload, len);
    unsigned seen = 0;
    uint32_t n = mpack_expect_map(&r);
    for (uint32_t i = 0; i < n && mpack_reader_error(&r) == mpack_ok; ++i) {
        de_ep_str k = de_ep_read_key(&r);
        if (de_ep_str_eq(k, "id")) {
            out->id = mpack_expect_u64(&r);
            seen |= 1u;
        } else if (de_ep_str_eq(k, "method")) {
            de_ep_read_str(&r, &out->method);
            seen |= 2u;
        } else if (de_ep_str_eq(k, "params")) {
            de_ep_read_raw(&r, &out->params);
            seen |= 4u;
        } else {
            mpack_discard(&r);
        }
    }
    mpack_done_map(&r);
    return mpack_reader_destroy(&r) == mpack_ok && (seen & 3u) == 3u;
}

void de_ep_write_result_begin(mpack_writer_t *w, uint64_t id) {
    mpack_start_map(w, 2);
    mpack_write_cstr(w, "id");
    mpack_write_u64(w, id);
    mpack_write_cstr(w, "result");
}

void de_ep_write_result_end(mpack_writer_t *w) {
    mpack_finish_map(w);
}

void de_ep_write_error(mpack_writer_t *w, uint64_t id, de_ep_error code, const char *message) {
    mpack_start_map(w, 2);
    mpack_write_cstr(w, "id");
    mpack_write_u64(w, id);
    mpack_write_cstr(w, "error");
    mpack_start_map(w, 2);
    mpack_write_cstr(w, "code");
    mpack_write_i32(w, (int32_t)code);
    mpack_write_cstr(w, "message");
    mpack_write_cstr(w, message ? message : "");
    mpack_finish_map(w);
    mpack_finish_map(w);
}

void de_ep_write_notification_begin(mpack_writer_t *w, const char *topic, uint64_t seq) {
    mpack_start_map(w, 3);
    mpack_write_cstr(w, "topic");
    mpack_write_cstr(w, topic);
    mpack_write_cstr(w, "seq");
    mpack_write_u64(w, seq);
    mpack_write_cstr(w, "data");
}

void de_ep_write_notification_end(mpack_writer_t *w) {
    mpack_finish_map(w);
}

void de_ep_write_request_begin(mpack_writer_t *w, uint64_t id, const char *method) {
    mpack_start_map(w, 3);
    mpack_write_cstr(w, "id");
    mpack_write_u64(w, id);
    mpack_write_cstr(w, "method");
    mpack_write_cstr(w, method);
    mpack_write_cstr(w, "params");
}

void de_ep_write_request_end(mpack_writer_t *w) {
    mpack_finish_map(w);
}

/* A reader over a request's params; absent params read as the empty map. */
static void de_ep__params_reader(const de_ep_request *req, mpack_reader_t *r) {
    static const unsigned char empty_map[1] = {0x80};
    if (req->params.len == 0)
        mpack_reader_init_data(r, (const char *)empty_map, 1);
    else
        mpack_reader_init_data(r, req->params.ptr, req->params.len);
}

